<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'

type Value = string | number | null
type Basis = Record<string, Value> & { qrsNo: string; issueState: number; curStage: string; dataStamp: number }
type Child = Record<string, string | number>
type Field = { key: string; label?: string; type?: 'number' | 'date' | 'textarea'; required?: boolean; readonly?: boolean }
type Section = { id: string; title: string; stage: string; keys: string[]; fields: Field[]; parent?: string }
const props = defineProps<{ developmentPreview?: boolean; currentUserNo?: string; initialQrsNo?: string; readOnly?: boolean }>()
const emit = defineEmits<{ close: []; openErfInfo: [erfNo: string] }>()
const dev = computed(() => import.meta.env.DEV && props.developmentPreview !== false)
const basisKey = 'ymes-dev-mock:wip-8d-basis-factory:state:v1'
const childKey = 'ymes-dev-mock:wip-8d-maintain:state:v1'
const filterFields = ['qrsNo','qrsSummary','factoryNo','projectDepartment','projectManager'] as const
const gridColumns = ['qrsNo','qrsClass','qrsSummary','lotNo','lotQty','sampleQty','errorQty','factoryNo','areaNo','moNo','customerNo','productNo','productVersion','roNo','opNo','createDate','equipmentNo','erfNo','holdDescription','description','projectDepartment','projectManager','projectManagerName','curStage','planCloseDate','lastUpdateDate','summaryDescription','dispHour','dispCost','summaryDepartment','summaryUserNo','summaryUserName','closeType','closeDepartment','closeUserNo','closeUserName','closeDate','creator'] as const
type FilterKey = typeof filterFields[number]
const filters = reactive<Record<FilterKey,string>>({ qrsNo:'', qrsSummary:'', factoryNo:'', projectDepartment:'', projectManager:'' })
const checked = reactive<Record<FilterKey,boolean>>({ qrsNo:false, qrsSummary:false, factoryNo:false, projectDepartment:false, projectManager:false })
const classes = ref<number[]>([])
const dates = reactive({ createFrom:'', createTo:'', planFrom:'', planTo:'', createChecked:false, planChecked:false })
const basisRows = ref<Basis[]>([])
const results = ref<Basis[]>([])
const searched = ref(false)
const activeNo = ref('')
const detailNo = ref('')
const active = computed(() => results.value.find(row => row.qrsNo === activeNo.value) || null)
const current = computed(() => basisRows.value.find(row => row.qrsNo === detailNo.value) || null)
const locked = computed(() => props.readOnly === true || current.value?.curStage === 'D9' || !!current.value?.closeDate)
const message = ref('選擇條件後按 Query；只列 Active 且未結案的 8D 單。')
const error = ref('')
const stageTabs = [ ['basis','Basis','N/A'], ['d1','Create Team','D1'], ['d2','Problem Description','D2'], ['d3','Immediate Action','D3'], ['d4','Cause Analysis','D4'], ['d5','Disposition','D5'], ['d6','Execute Verification','D6'], ['d7','Precausion','D7'], ['d8','Summary','D8'], ['d9','8DClose','D9'] ] as const
const tab = ref<string>('basis')
const sections: Section[] = [
  {id:'d1',title:'D1 TeamMember',stage:'D1',keys:['memberType','memberNo'],fields:[{key:'memberType',label:'MemberType',type:'number',required:true},{key:'memberNo',label:'MemberNo',required:true},{key:'memberName',label:'MemberName',required:true},{key:'departmentNo',label:'DepartmentNo'},{key:'taskDesc',label:'TaskDesc',required:true},{key:'telNo',label:'TelNo'},{key:'email',label:'EMail'},{key:'pmFlag',label:'PMFlag',type:'number'},{key:'description',label:'Description'}]},
  {id:'d2',title:'D2 Question',stage:'D2',keys:['sequenceNo'],fields:[{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'questionDesc',label:'QuestionDesc',type:'textarea',required:true}]},
  {id:'d3',title:'D3 Action',stage:'D3',keys:['mainSN'],fields:[{key:'mainSN',label:'MainSN',type:'number',required:true},{key:'planAction',label:'PlanAction',type:'textarea',required:true},{key:'dutyDepartment',label:'DutyDepartment',required:true},{key:'dutyMember',label:'DutyMember'},{key:'dutyMemberName',label:'DutyMemberName',required:true},{key:'planFinishDate',label:'PlanFinishDate',type:'date',required:true},{key:'description',label:'Description'}]},
  {id:'d3detail',title:'D3 Action Detail',stage:'D3',parent:'d3',keys:['mainSN','sequenceNo'],fields:[{key:'mainSN',label:'MainSN',type:'number',required:true,readonly:true},{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'subAction',label:'SubAction',type:'textarea',required:true},{key:'dutyDepartment',label:'DutyDepartment',required:true},{key:'dutyMember',label:'DutyMember'},{key:'dutyMemberName',label:'DutyMemberName',required:true},{key:'planFinishDate',label:'PlanFinishDate',type:'date',required:true},{key:'description',label:'Description'}]},
  {id:'d4',title:'D4 RootCause',stage:'D4',keys:['reasonNo'],fields:[{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'reasonNo',label:'ReasonNo',required:true},{key:'frequency',label:'Frequency',type:'number'},{key:'description',label:'Description',type:'textarea'}]},
  {id:'d5',title:'D5 Disposition',stage:'D5',parent:'d4',keys:['sequenceNo','reasonNo'],fields:[{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'reasonNo',label:'ReasonNo',required:true,readonly:true},{key:'disposition',label:'Disposition',type:'textarea',required:true},{key:'dutyDepartment',label:'DutyDepartment',required:true},{key:'dutyMember',label:'DutyMember',required:true},{key:'dutyMemberName',label:'DutyMemberName',required:true},{key:'planFinishDate',label:'PlanFinishDate',type:'date',required:true},{key:'description',label:'Description'}]},
  {id:'d6',title:'D6 QA Verification',stage:'D6',parent:'d5',keys:['reasonNo','dispositionSN'],fields:[{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'reasonNo',label:'ReasonNo',required:true,readonly:true},{key:'dispositionSN',label:'DispositionSN',type:'number',required:true,readonly:true},{key:'qaDescription',label:'QADescription',type:'textarea',required:true},{key:'qaResult',label:'QAResult',required:true},{key:'qaDepartment',label:'QADepartment',required:true},{key:'verifier',label:'Verifier',required:true},{key:'verifierName',label:'VerifierName',required:true},{key:'verifyDate',label:'VerifyDate',type:'date',required:true},{key:'lotNo',label:'LotNo'},{key:'ipqcFormNo',label:'IPQCFormNo'},{key:'dispHours',label:'DispHours',type:'number'},{key:'consumeCost',label:'ConsumeCost',type:'number'},{key:'memo',label:'Memo'}]},
  {id:'d7',title:'D7 Prevention',stage:'D7',keys:['sequenceNo'],fields:[{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'preventionItem',label:'PreventionItem',required:true},{key:'description',label:'Description',type:'textarea'},{key:'mainDepartment',label:'MainDepartment',required:true},{key:'director',label:'Director',required:true},{key:'directorName',label:'DirectorName',required:true},{key:'planFinishDate',label:'PlanFinishDate',type:'date',required:true}]},
  {id:'d7track',title:'D7 Prevention Track',stage:'D7',parent:'d7',keys:['mainSN','sequenceNo'],fields:[{key:'mainSN',label:'MainSN',type:'number',required:true,readonly:true},{key:'sequenceNo',label:'SequenceNo',type:'number',required:true},{key:'finishDate',label:'FinishDate',type:'date',required:true},{key:'trackDepartment',label:'TrackDepartment',required:true},{key:'tracker',label:'Tracker',required:true},{key:'trackerName',label:'TrackerName',required:true},{key:'traceDescription',label:'TraceDescription',type:'textarea',required:true},{key:'traceResult',label:'TraceResult',required:true}]},
]
const child = reactive<Record<string, Child[]>>({})
const selectedKey = reactive<Record<string,string>>({})
const editSection = ref<Section | null>(null)
const editMode = ref<'add'|'edit'|'verify'>('add')
const originalKey = ref('')
const form = reactive<Child>({})
const confirmDelete = ref<Section | null>(null)
const summary = reactive({ qrsSummary:'', summaryDescription:'', summaryDepartment:'', summaryUserNo:'', summaryUserName:'', dispHour:'0', dispCost:'0', autoClose:false })
const attachments = reactive<Record<string,string[]>>({})
const fishbone = ref(false)

function loadBasis(): void {
  if (!dev.value) return
  try { const data = JSON.parse(window.localStorage.getItem(basisKey) || 'null') as unknown; if (Array.isArray(data)) { basisRows.value = data.filter(row => row && typeof row.qrsNo === 'string' && typeof row.issueState === 'number') as Basis[]; return } } catch { /* DEV fallback */ }
  const defaults: Record<string,Value> = {lotNo:'',lotQty:0,sampleQty:0,errorQty:0,factoryNo:'FACTORY-A',areaNo:'A01',moNo:'',customerNo:'',productNo:'',productVersion:'',roNo:'',opNo:'',equipmentNo:'',erfNo:'',holdDescription:'',description:'',projectManagerName:'示範經理',lastUpdateDate:'2026-11-20 09:00:00',summaryDescription:'',dispHour:0,dispCost:0,summaryDepartment:'',summaryUserNo:'',summaryUserName:'',closeType:null,closeDepartment:'',closeUserNo:'',closeUserName:'',closeDate:null,creator:'DEV',reviser:'',reviseDate:null}
  basisRows.value = [
    {...defaults,qrsNo:'QRS-DEV-001',qrsClass:4,qrsSummary:'示範矯正單',issueState:0,curStage:'N/A',dataStamp:0,projectDepartment:'QA',projectManager:'DEV-MGR',planCloseDate:'2026-11-27',createDate:'2026-11-20 09:00:00'},
    {...defaults,qrsNo:'QRS-DEV-002',qrsClass:3,qrsSummary:'設備異常 8D 示範',issueState:2,curStage:'N/A',dataStamp:1,projectDepartment:'ENG',projectManager:'DEV-MGR',planCloseDate:'2026-11-27',createDate:'2026-11-19 13:00:00',erfNo:'DEV-ERF-002',lotNo:'DEV-LOT-002',lotQty:5,errorQty:1,moNo:'MO-DEV-01',customerNo:'CUS-B',productNo:'PRD-B',productVersion:'1',roNo:'RO-DEV-01',opNo:'OP-TEST',equipmentNo:'EQ-DEV-01',holdDescription:'設備點檢異常',description:'完成處置'},
  ]
}
function saveBasis(): void { if (dev.value) window.localStorage.setItem(basisKey, JSON.stringify(basisRows.value)) }
function loadChild(): void {
  for (const section of sections) child[section.id] = []
  child.release = []; child.releaseLog = []
  for (const stage of stageTabs) attachments[stage[2]] = []
  try { const value = JSON.parse(window.localStorage.getItem(childKey) || '{}') as Record<string, {tables?: Record<string,Child[]>; attachments?: Record<string,string[]>}>; const record = value[detailNo.value]; if (record) { for (const section of sections) child[section.id] = Array.isArray(record.tables?.[section.id]) ? record.tables![section.id] : []; for (const key of ['release','releaseLog']) child[key] = Array.isArray(record.tables?.[key]) ? record.tables![key] : []; for (const stage of stageTabs) attachments[stage[2]] = Array.isArray(record.attachments?.[stage[2]]) ? record.attachments![stage[2]] : [] } } catch { /* DEV empty */ }
}
function saveChild(): void { if (!dev.value) return; let value: Record<string,unknown> = {}; try { value = JSON.parse(window.localStorage.getItem(childKey) || '{}') as Record<string,unknown> } catch { /* DEV reset */ }; const tables: Record<string,Child[]> = {}; for (const section of sections) tables[section.id] = child[section.id]; tables.release = child.release; tables.releaseLog = child.releaseLog; value[detailNo.value] = {tables,attachments}; window.localStorage.setItem(childKey,JSON.stringify(value)) }
function query(): void {
  error.value = ''; if (!dev.value) { error.value = '正式 API 尚未接入。'; return }
  loadBasis()
  if ((dates.createChecked && (!dates.createFrom || !dates.createTo || dates.createFrom > dates.createTo)) || (dates.planChecked && (!dates.planFrom || !dates.planTo || dates.planFrom > dates.planTo))) { error.value = '日期起迄不正確。'; return }
  results.value = basisRows.value.filter(row => row.issueState === 2 && !row.closeDate && (!classes.value.length || classes.value.includes(Number(row.qrsClass))) && filterFields.every(key => !checked[key] || !filters[key].trim() || String(row[key] ?? '').toUpperCase().includes(filters[key].trim().toUpperCase())) && (!dates.createChecked || (String(row.createDate ?? '').slice(0,10) >= dates.createFrom && String(row.createDate ?? '').slice(0,10) <= dates.createTo)) && (!dates.planChecked || (String(row.planCloseDate ?? '').slice(0,10) >= dates.planFrom && String(row.planCloseDate ?? '').slice(0,10) <= dates.planTo))).sort((a,b) => a.qrsNo.localeCompare(b.qrsNo))
  searched.value = true; activeNo.value = ''; message.value = `查得 ${results.value.length} 筆已簽核且未結案的 8D 單。`
}
function openDetail(row = active.value): void { if (!row) { error.value = '請先選取資料。'; return }; detailNo.value = row.qrsNo; for (const section of sections) selectedKey[section.id] = ''; tab.value = stageTabs.find(item => item[2] === row.curStage)?.[0] || 'basis'; loadChild(); Object.assign(summary,{qrsSummary:String(row.qrsSummary ?? ''),summaryDescription:String(row.summaryDescription ?? ''),summaryDepartment:String(row.summaryDepartment ?? ''),summaryUserNo:String(row.summaryUserNo ?? ''),summaryUserName:String(row.summaryUserName ?? ''),dispHour:String(row.dispHour ?? 0),dispCost:String(row.dispCost ?? 0),autoClose:false}); error.value = '' }
function closeDetail(): void { if (props.readOnly) { emit('close'); return }; detailNo.value = ''; query() }
function rowKey(section: Section, row: Child): string { return section.keys.map(key => String(row[key] ?? '')).join('|') }
function selectedRow(section: Section): Child | null { return child[section.id]?.find(row => rowKey(section,row) === selectedKey[section.id]) || null }
function nextNumber(section: Section, key: string, parent?: Child | null): number { const rows = child[section.id] || []; return Math.max(0,...rows.filter(row => !parent || !section.parent || Number(row.mainSN) === Number(parent.mainSN ?? parent.sequenceNo)).map(row => Number(row[key]) || 0)) + 1 }
function advance(stage: string): void { if (!current.value) return; const old = current.value.curStage; if (old === 'D9') return; if (old === 'N/A' || Number(stage.slice(1)) > Number(old.slice(1))) { current.value.curStage = stage; current.value.dataStamp++; current.value.lastUpdateDate = new Date().toISOString().slice(0,19).replace('T',' '); saveBasis() } }
function openEditor(section: Section, mode: 'add'|'edit'|'verify'): void {
  error.value = ''; if (!dev.value || !current.value || locked.value) return
  if (section.id !== 'd1' && !child.d1?.length) { error.value = '請先建立 D1 TeamMember。'; return }
  const parent = section.parent ? selectedRow(sections.find(item => item.id === section.parent)!) : null
  if (section.parent && !parent) { error.value = `請先選取 ${section.parent.toUpperCase()} 資料列。`; return }
  const chosen = selectedRow(section)
  if (mode !== 'add' && !chosen) { error.value = '請先選取明細列。'; return }
  for (const key of Object.keys(form)) delete form[key]
  if (mode === 'add') {
    for (const field of section.fields) form[field.key] = ''
    if (section.fields.some(field => field.key === 'sequenceNo')) form.sequenceNo = nextNumber(section,'sequenceNo',parent)
    if (section.fields.some(field => field.key === 'mainSN')) form.mainSN = section.parent ? Number(parent?.mainSN ?? parent?.sequenceNo) : nextNumber(section,'mainSN')
    if (section.id === 'd1') { form.memberType = 1; form.memberNo = props.currentUserNo || 'DEV'; form.memberName = props.currentUserNo || 'DEV'; form.pmFlag = 0 }
    if (section.id === 'd5') form.reasonNo = String(parent?.reasonNo || '')
    if (section.id === 'd6') { form.reasonNo = String(parent?.reasonNo || ''); form.dispositionSN = Number(parent?.sequenceNo || 0); form.qaResult = 'OK' }
    if (section.id === 'd3detail' || section.id === 'd7track') form.mainSN = Number(parent?.mainSN ?? parent?.sequenceNo)
  } else Object.assign(form,chosen)
  originalKey.value = chosen ? rowKey(section,chosen) : ''; editSection.value = section; editMode.value = mode
}
function saveEditor(): void {
  const section = editSection.value; if (!section || !current.value) return
  if (locked.value) { error.value = '此 8D 已結案，不可修改。'; return }
  if (editMode.value === 'verify' && (!String(form.actionResult || '').trim() || !String(form.qaUserNo || '').trim() || !String(form.actualFinishDate || '').trim())) { error.value = 'Verify 需填 ActionResult、QAUserNo 與 ActualFinishDate。'; return }
  for (const field of section.fields) if (field.required && String(form[field.key] ?? '').trim() === '') { error.value = `${field.label || field.key} 不可空白。`; return }
  for (const field of section.fields) if (field.type === 'number' && form[field.key] !== '' && !Number.isFinite(Number(form[field.key]))) { error.value = `${field.label || field.key} 必須是數字。`; return }
  if (section.id === 'd5' && !child.d4.some(row => row.reasonNo === form.reasonNo)) { error.value = 'D5 必須對應 D4 原因。'; return }
  const rows = child[section.id]; const saved: Child = {...form, qrsNo:detailNo.value}
  for (const field of section.fields) if (field.type === 'number' && saved[field.key] !== '') saved[field.key] = Number(saved[field.key])
  const id = rowKey(section,saved)
  if (editMode.value === 'add' && rows.some(row => rowKey(section,row) === id)) { error.value = '相同明細鍵值已存在。'; return }
  if (editMode.value !== 'add' && id !== originalKey.value) { error.value = '編輯時不可修改明細鍵值。'; return }
  if (editMode.value === 'add') { saved.creator = props.currentUserNo || 'DEV'; saved.createDate = new Date().toISOString().slice(0,19).replace('T',' '); rows.push(saved); advance(section.stage) }
  else { const existing = selectedRow(section); if (existing) Object.assign(existing,saved) }
  selectedKey[section.id] = id; saveChild(); editSection.value = null; message.value = `${section.title} 的 DEV 假資料已${editMode.value === 'add' ? '新增' : '修改'}。`; error.value = ''
}
function deleteRow(section: Section): void {
  if (locked.value) { error.value = '此 8D 已結案，不可刪除。'; confirmDelete.value = null; return }
  const row = selectedRow(section); if (!row) { error.value = '請先選取明細列。'; return }
  if (section.id === 'd4' && child.d5.some(item => item.reasonNo === row.reasonNo)) { error.value = '此原因已有 D5 處置，請先處理關聯資料。'; return }
  if (section.id === 'd5' && child.d6.some(item => item.reasonNo === row.reasonNo && Number(item.dispositionSN) === Number(row.sequenceNo))) { error.value = '此處置已有 D6 驗證，請先處理關聯資料。'; return }
  if (section.id === 'd7' && child.d7track.some(item => Number(item.mainSN) === Number(row.sequenceNo))) { error.value = '此預防措施已有 Track，請先處理追蹤資料。'; return }
  child[section.id] = child[section.id].filter(item => rowKey(section,item) !== rowKey(section,row))
  if (section.id === 'd3') child.d3detail = child.d3detail.filter(item => Number(item.mainSN) !== Number(row.mainSN))
  selectedKey[section.id] = ''; confirmDelete.value = null; saveChild(); message.value = `${section.title} 的 DEV 假資料已刪除。`; error.value = ''
}
function verifyAction(section: Section): void { const row = selectedRow(section); if (!row) { error.value = '請先選取 D3 行動列。'; return }; openEditor(section,'verify'); form.actionResult = String(row.actionResult || 'OK'); form.qaUserNo = props.currentUserNo || 'DEV'; form.qaUserName = props.currentUserNo || 'DEV'; form.actualFinishDate = new Date().toISOString().slice(0,10); form.qaMemo = String(row.qaMemo || '') }
function saveBasisDetails(): void { const row = current.value; if (!row || locked.value) return; for (const key of ['projectDepartment','projectManager','planCloseDate']) if (!String(row[key] ?? '').trim()) { error.value = `${key} 不可空白。`; return }; row.dataStamp++; row.lastUpdateDate = new Date().toISOString().slice(0,19).replace('T',' '); saveBasis(); message.value = 'Basis 的 DEV 專案資料已儲存。'; error.value = '' }
function saveSummary(): void {
  const row = current.value; if (!row || locked.value) return
  if (!child.d1.length || !child.d3.length || child.d3.some(action => !action.actionResult)) { error.value = 'D8 需先有 D1 TeamMember，且所有 D3 Action 已驗證。'; return }
  for (const key of ['qrsSummary','summaryDescription','summaryDepartment','summaryUserNo']) if (!String(summary[key as keyof typeof summary]).trim()) { error.value = `${key} 不可空白。`; return }
  if (!Number.isFinite(Number(summary.dispHour)) || !Number.isFinite(Number(summary.dispCost))) { error.value = 'DispHour / DispCost 必須是數字。'; return }
  const today = new Date().toISOString().slice(0,10)
  Object.assign(row,{qrsSummary:summary.qrsSummary,summaryDescription:summary.summaryDescription,summaryDepartment:summary.summaryDepartment,summaryUserNo:summary.summaryUserNo,summaryUserName:summary.summaryUserName,dispHour:Number(summary.dispHour),dispCost:Number(summary.dispCost),curStage:summary.autoClose ? 'D9' : 'D8',closeDate:summary.autoClose ? today : null,closeType:summary.autoClose ? 1 : null,closeDepartment:summary.autoClose ? summary.summaryDepartment : '',closeUserNo:summary.autoClose ? summary.summaryUserNo : '',closeUserName:summary.autoClose ? summary.summaryUserName : ''})
  if (summary.autoClose) { child.releaseLog = [{qrsNo:row.qrsNo,releaseType:1,releaseMemo:summary.summaryDescription,releaseDepartment:summary.summaryDepartment,releaser:summary.summaryUserNo,releaserName:summary.summaryUserName,releaseDate:today}]; if (child.release.length) child.release[0].issueState = 2 }
  else if (!child.release.length) child.release = [{qrsNo:row.qrsNo,issueState:0,creator:props.currentUserNo || 'DEV',createDate:new Date().toISOString().slice(0,19).replace('T',' ')}]
  row.dataStamp++; saveBasis(); saveChild(); message.value = summary.autoClose ? 'DEV 總結並模擬自動結案。' : 'DEV 總結已存，待結案申請。'; error.value = ''
}
function takeFile(event: Event): void { const input = event.target as HTMLInputElement; const file = input.files?.[0]; const row = current.value; if (!file || !row || locked.value) return; const stage = stageTabs.find(item => item[0] === tab.value)?.[2] || 'N/A'; if (file.name.length > 60) { error.value = '附件名稱超過 60 字元。'; return }; if (attachments[stage].includes(file.name)) { error.value = '同階段同名附件已存在。'; return }; attachments[stage].push(file.name); saveChild(); message.value = `${stage} DEV 假附件 ${file.name} 已加入；未上傳檔案內容。`; input.value = '' }
onMounted(() => { if (!dev.value) return; loadBasis(); if (props.initialQrsNo) { checked.qrsNo = true; filters.qrsNo = props.initialQrsNo; query(); const row = basisRows.value.find(item => item.qrsNo === props.initialQrsNo && (props.readOnly || item.issueState !== -1)); if (row) openDetail(row) } })
watch(dev, enabled => { if (!enabled) { basisRows.value = []; results.value = []; activeNo.value = ''; detailNo.value = ''; searched.value = false; editSection.value = null; confirmDelete.value = null; fishbone.value = false; for (const section of sections) child[section.id] = []; child.release = []; child.releaseLog = []; for (const stage of stageTabs) attachments[stage[2]] = [] } })
</script>

<template>
  <section class="wp802">
    <div v-if="dev" class="dev-note">DEV 假資料預覽 · 主單與 WP801 共用本機資料；明細、附件及階段操作僅存在瀏覽器。</div>
    <h1>8D 矯正單維護作業 <small>8D MAINTAIN · WP802</small></h1>
    <p v-if="error" class="feedback error" role="alert">{{ error }}</p><p v-else class="feedback" role="status">{{ message }}</p>
    <template v-if="!detailNo">
      <fieldset><legend>Query</legend><div class="query-grid"><label v-for="key in filterFields" :key="key" class="query-item"><input v-model="checked[key]" type="checkbox" :disabled="!dev">{{ key }}<input v-model="filters[key]" class="yellow" :disabled="!dev || !checked[key]" @keydown.enter.prevent="query"></label><div class="query-item"><label><input v-model="classes" type="checkbox" :value="1">In Line QC</label><label><input v-model="classes" type="checkbox" :value="2">Off Line QC</label><label><input v-model="classes" type="checkbox" :value="3">WIPERF</label><label><input v-model="classes" type="checkbox" :value="4">Other</label></div><label class="query-item"><input v-model="dates.createChecked" type="checkbox">Create Date <input v-model="dates.createFrom" type="date" class="yellow"><span>～</span><input v-model="dates.createTo" type="date" class="yellow"></label><label class="query-item"><input v-model="dates.planChecked" type="checkbox">PlanCloseDate <input v-model="dates.planFrom" type="date" class="yellow"><span>～</span><input v-model="dates.planTo" type="date" class="yellow"></label><button type="button" class="mes-button" :disabled="!dev" @click="query">Query (&Q)</button></div></fieldset>
      <fieldset class="result"><legend>8DBASISFACTORYDATA</legend><div class="result-content"><div class="table-wrap"><table><thead><tr><th v-for="key in gridColumns" :key="key">{{ key }}</th></tr></thead><tbody><tr v-for="row in results" :key="row.qrsNo" :class="{selected: activeNo === row.qrsNo}" @click="activeNo = row.qrsNo" @dblclick="openDetail(row)"><td v-for="key in gridColumns" :key="key">{{ row[key] }}</td></tr><tr v-if="!results.length"><td :colspan="gridColumns.length" class="empty">{{ searched ? '沒有符合資料' : '請按 Query 查詢' }}</td></tr></tbody></table></div><aside><button type="button" class="mes-button" :disabled="!dev || !active" @click="openDetail()">Maintain</button><button type="button" class="mes-button" @click="emit('close')">Close (&X)</button></aside></div><div class="status">UserNo: {{ currentUserNo || 'DEV' }}　資料總筆數 {{ results.length }}</div></fieldset>
    </template>
    <template v-else-if="current"><div class="detail-head"><span>QRSNo: <strong>{{ current.qrsNo }}</strong>　CurStage: <strong>{{ current.curStage }}</strong>　IssueState: {{ current.issueState }} <em v-if="readOnly">8DQuery 唯讀</em></span><button type="button" class="mes-button" @click="closeDetail">Close</button></div><div class="tabs" role="tablist"><button v-for="item in stageTabs" :key="item[0]" type="button" class="mes-button" :class="{selected:tab === item[0]}" @click="tab = item[0]; error = ''">{{ item[1] }}</button></div>
      <fieldset v-if="tab === 'basis'"><legend>8DBASISFACTORYDATA</legend><div class="basis-grid"><label v-for="key in ['qrsNo','qrsSummary','factoryNo','areaNo','erfNo','lotNo','productNo','opNo','equipmentNo','curStage','holdDescription']" :key="key">{{ key }}<input :value="current[key] ?? ''" class="yellow" readonly></label><label>ProjectDepartment<input v-model="current.projectDepartment" class="yellow" :readonly="locked"></label><label>ProjectManager<input v-model="current.projectManager" class="yellow" :readonly="locked"></label><label>PlanCloseDate<input v-model="current.planCloseDate" type="date" class="yellow" :readonly="locked"></label></div><div class="buttons"><button type="button" class="mes-button" :disabled="locked" @click="saveBasisDetails">Confirm</button><button type="button" class="mes-button" :disabled="!current.erfNo" @click="emit('openErfInfo',String(current.erfNo))">ERFINFO</button></div></fieldset>
      <template v-else-if="['d1','d2','d3','d4','d5','d6','d7'].includes(tab)"><fieldset v-for="section in sections.filter(item => item.id === tab || (tab === 'd3' && item.id === 'd3detail') || (tab === 'd7' && item.id === 'd7track'))" :key="section.id" class="section"><legend>{{ section.title }}</legend><div class="result-content"><div class="table-wrap"><table><thead><tr><th v-for="field in section.fields" :key="field.key">{{ field.label || field.key }}</th><th>Creator</th><th>CreateDate</th><th v-if="section.id === 'd3' || section.id === 'd3detail'">ActionResult</th></tr></thead><tbody><tr v-for="row in child[section.id]" :key="rowKey(section,row)" :class="{selected:selectedKey[section.id] === rowKey(section,row)}" @click="selectedKey[section.id] = rowKey(section,row)"><td v-for="field in section.fields" :key="field.key">{{ row[field.key] }}</td><td>{{ row.creator }}</td><td>{{ row.createDate }}</td><td v-if="section.id === 'd3' || section.id === 'd3detail'">{{ row.actionResult }}</td></tr><tr v-if="!child[section.id]?.length"><td :colspan="section.fields.length + (section.id === 'd3' || section.id === 'd3detail' ? 3 : 2)" class="empty">無資料</td></tr></tbody></table></div><aside><button type="button" class="mes-button" :disabled="locked" @click="openEditor(section,'add')">ADD (&A)</button><button type="button" class="mes-button" :disabled="locked || !selectedRow(section)" @click="openEditor(section,'edit')">EDIT (&E)</button><button type="button" class="mes-button" :disabled="locked || !selectedRow(section)" @click="confirmDelete = section">DEL (&D)</button><button v-if="section.id === 'd3' || section.id === 'd3detail'" type="button" class="mes-button" :disabled="locked || !selectedRow(section)" @click="verifyAction(section)">Verify</button><button v-if="section.id === 'd4'" type="button" class="mes-button" @click="fishbone = true">FishBone</button></aside></div></fieldset></template>
      <fieldset v-else-if="tab === 'd8'" :disabled="locked"><legend>Summary</legend><div class="basis-grid"><label>QRSSummary<input v-model="summary.qrsSummary" class="yellow"></label><label>SummaryDepartment<input v-model="summary.summaryDepartment" class="yellow"></label><label>SummaryUserNo<input v-model="summary.summaryUserNo" class="yellow"></label><label>SummaryUserName<input v-model="summary.summaryUserName" class="yellow"></label><label>DispHour<input v-model="summary.dispHour" type="number" class="yellow"></label><label>DispCost<input v-model="summary.dispCost" type="number" class="yellow"></label><label class="wide">SummaryDescription<textarea v-model="summary.summaryDescription" class="yellow" rows="4"></textarea></label><label><input v-model="summary.autoClose" type="checkbox">DEV 模擬 8DReportAutoClose=Y</label></div><div class="buttons"><button type="button" class="mes-button" :disabled="locked" @click="saveSummary">OK</button></div></fieldset>
      <fieldset v-else><legend>8DClose</legend><div class="basis-grid"><label>QRSNo<input :value="current.qrsNo" readonly></label><label>CurStage<input :value="current.curStage" readonly></label><label>CloseDate<input :value="current.closeDate ?? ''" readonly></label><label>CloseType<input :value="current.closeType ?? ''" readonly></label><label>SummaryDescription<input :value="current.summaryDescription ?? ''" readonly></label><label>Release IssueState<input :value="child.release?.[0]?.issueState ?? ''" readonly></label><label>ReleaseLog Type<input :value="child.releaseLog?.[0]?.releaseType ?? ''" readonly></label></div><p>結案申請與簽核由 WP803 處理；此頁顯示目前主單結果。</p></fieldset>
      <fieldset class="attach"><legend>{{ stageTabs.find(item => item[0] === tab)?.[2] }} Attach</legend><div class="attachment-row" v-for="name in attachments[stageTabs.find(item => item[0] === tab)?.[2] || 'N/A'] || []" :key="name"><span>{{ name }}</span><button type="button" class="mes-button" @click="message = 'DEV 假附件只有檔名，沒有真實檔案內容。'">View</button><button type="button" class="mes-button" :disabled="locked" @click="attachments[stageTabs.find(item => item[0] === tab)?.[2] || 'N/A'] = attachments[stageTabs.find(item => item[0] === tab)?.[2] || 'N/A'].filter(item => item !== name); saveChild()">Delete</button></div><label v-if="!locked">Take Attach File <input type="file" @change="takeFile"></label></fieldset>
    </template>
    <div v-if="editSection" class="overlay" @click.self="editSection = null"><div class="modal" role="dialog" aria-modal="true"><header>{{ editSection.title }} · {{ editMode.toUpperCase() }}</header><div class="basis-grid"><label v-for="field in editSection.fields" :key="field.key">{{ field.label || field.key }}<textarea v-if="field.type === 'textarea'" v-model="form[field.key]" class="yellow" rows="3" :readonly="field.readonly || editMode === 'verify'"></textarea><input v-else v-model="form[field.key]" :type="field.type === 'date' ? 'date' : field.type === 'number' ? 'number' : 'text'" class="yellow" :readonly="field.readonly || editMode === 'verify'"></label><template v-if="editMode === 'verify'"><label>ActionResult<input v-model="form.actionResult" class="yellow"></label><label>QAUserNo<input v-model="form.qaUserNo" class="yellow"></label><label>QAUserName<input v-model="form.qaUserName" class="yellow"></label><label>ActualFinishDate<input v-model="form.actualFinishDate" type="date" class="yellow"></label><label>QAMemo<input v-model="form.qaMemo" class="yellow"></label></template></div><div class="buttons"><button type="button" class="mes-button primary" @click="saveEditor">Confirm</button><button type="button" class="mes-button" @click="editSection = null">Close</button></div></div></div>
    <div v-if="confirmDelete" class="overlay"><div class="modal small" role="alertdialog" aria-modal="true">確定刪除 {{ confirmDelete.title }} 選取列？<div class="buttons"><button type="button" class="mes-button primary" @click="deleteRow(confirmDelete)">確定</button><button type="button" class="mes-button" @click="confirmDelete = null">取消</button></div></div></div>
    <div v-if="fishbone" class="overlay" @click.self="fishbone = false"><div class="modal" role="dialog" aria-modal="true"><header>FishBone · {{ detailNo }}</header><div class="fishbone"><div v-for="part in ['Man','Machine','Material','Method','Measurement','Environment']" :key="part"><strong>{{ part }}</strong><ul><li v-for="row in child.d4" :key="row.reasonNo">{{ row.reasonNo }} · {{ row.description || '—' }}</li></ul></div></div><div class="buttons"><button type="button" class="mes-button" @click="fishbone = false">Close</button></div></div></div>
  </section>
</template>

